import { Context } from "effect";
import { HttpApiMiddleware, HttpApiSecurity } from "effect/http-api";
import { Tunnel } from "../tunnel.js";
import { UnauthorizedError } from "./errors.js";

export class OpenTunnelAuthorizationToken extends Context.Service<
  OpenTunnelAuthorizationToken,
  Tunnel.Token
>()("@opentunnel/protocol/OpenTunnelAuthorizationToken") {}

export class OpenTunnelAuthorization extends HttpApiMiddleware.Service<
  OpenTunnelAuthorization,
  { provides: OpenTunnelAuthorizationToken }
>()("@opentunnel/protocol/OpenTunnelAuthorization", {
  security: { bearer: HttpApiSecurity.bearer },
  error: UnauthorizedError,
}) {}

import { afterEach, beforeEach, describe, expect, test } from "bun:test";
import { ApiRetry } from "@opentunnel/protocol/api-retry";
import { create, OpenTunnelStorage, type OpenTunnelPromiseClient } from "../src/promise/index.js";
import { testIdentity } from "./fake-relay.js";

/** Answers each request with the next status (an error page, `Retry-After: 0`), then with the identity's certificate. */
const flakyApi = (statuses: number[], certificate: () => string) => {
  const seen: string[] = [];
  const server = Bun.serve({
    port: 0,
    hostname: "127.0.0.1",
    fetch(request) {
      const url = new URL(request.url);
      const status = statuses[seen.length];
      seen.push(`${request.method} ${url.pathname}`);
      if (status !== undefined) {
        return new Response(`<html>error code: ${status}</html>`, {
          status,
          headers: { "content-type": "text/html", "retry-after": "0" },
        });
      }
      return Response.json({
        id: "cert",
        state: {
          type: "ready",
          certificate: certificate(),
          chain: "",
          expiry: new Date(Date.now() + 86_400_000).toISOString(),
        },
      });
    },
  });
  return { url: `http://127.0.0.1:${server.port}`, seen, stop: () => server.stop(true) };
};

let identity: Awaited<ReturnType<typeof testIdentity>>;
let store: ReturnType<typeof OpenTunnelStorage.memory>;
let api: ReturnType<typeof flakyApi> | undefined;
let client: OpenTunnelPromiseClient | undefined;

const start = (statuses: number[]) => {
  api = flakyApi(statuses, () => identity.certificate);
  client = create({ api: api.url, store });
  return { api, client };
};

beforeEach(async () => {
  identity = await testIdentity();
  store = OpenTunnelStorage.memory();
  await store.save("default", identity);
});

afterEach(async () => {
  await client?.dispose();
  api?.stop();
});

describe("API requests", () => {
  test("are retried after transient failures", async () => {
    const { api, client } = start([525, 502, 429]);
    const ensured = await client.tunnel.ensure();
    expect(ensured.certificate).toBe(identity.certificate);
    expect(api.seen).toHaveLength(4);
  });

  test("are not retried after client errors", async () => {
    const { api, client } = start([401]);
    await expect(client.tunnel.ensure()).rejects.toThrow("Failed to read certificate");
    expect(api.seen).toHaveLength(1);
  });

  test("keep a valid saved certificate while the API keeps failing", async () => {
    const { api, client } = start(Array(20).fill(525));
    const ensured = await client.tunnel.ensure();
    expect(ensured.certificate).toBe(identity.certificate);
    expect(api.seen).toHaveLength(ApiRetry.RETRIES + 1);
  });

  test("fail with the HTTP status and Cloudflare's meaning of it", async () => {
    await store.save("default", { ...identity, certificateExpiry: new Date(Date.now() - 1000) });
    const { client } = start(Array(20).fill(525));
    await expect(client.tunnel.ensure()).rejects.toThrow(
      "Failed to read certificate: Cloudflare 525: the SSL handshake with the server failed (HTTP 525)",
    );
  });

  test("create a tunnel again only when the first attempt cannot have arrived", async () => {
    await store.remove("default");
    const { api, client } = start([525, 520]);
    await expect(client.tunnel.create()).rejects.toThrow(
      "Failed to create tunnel: Cloudflare 520: the server returned an unknown error (HTTP 520)",
    );
    expect(api.seen).toEqual(["POST /api/tunnel", "POST /api/tunnel"]);
  });
});

export * as ApiRetry from "./api-retry.js";

/**
 * Retries of a failed API request, shared by both clients: capped exponential
 * backoff with jitter. See `docs/protocol.md` and `spec/vectors/api-retry.json`.
 */

export const RETRY_BASE_MS = 250;
export const RETRY_MAX_MS = 8000;
export const RETRIES = 6;

/**
 * How safely a request may be sent again after a failure. `idempotent`
 * requests (reads, binding the same CSR) are retried on any transient failure;
 * `once` requests (creating or deleting a tunnel) only when they cannot have
 * reached the API.
 */
export type Repeat = "idempotent" | "once";

/** Whether a response with `status` is a transient failure worth retrying. */
export const retryableStatus = (status: number, repeat: Repeat): boolean =>
  repeat === "idempotent"
    ? status === 429 || (status >= 500 && status <= 599)
    : // Rate limited, the API's own "unavailable", or Cloudflare could not reach the server at all.
      [429, 503, 521, 522, 523, 525].includes(status);

/**
 * The delay range in milliseconds before retry `attempt` (from 0):
 * `RETRY_BASE_MS` doubling up to `RETRY_MAX_MS`, between half of that and all
 * of it. A `Retry-After` in seconds is followed instead, up to `RETRY_MAX_MS`.
 */
export const retryDelayMs = (attempt: number, retryAfter?: string | null): readonly [number, number] => {
  const seconds = retryAfter?.trim();
  if (seconds && /^\d+$/.test(seconds)) {
    const delay = Math.min(Number(seconds) * 1000, RETRY_MAX_MS);
    return [delay, delay];
  }
  const delay = Math.min(RETRY_BASE_MS * 2 ** Math.min(attempt, 16), RETRY_MAX_MS);
  return [delay / 2, delay];
};

const CLOUDFLARE_REASONS: Record<number, string> = {
  520: "the server returned an unknown error",
  521: "the server refused the connection",
  522: "the connection to the server timed out",
  523: "the server is unreachable",
  524: "the server did not answer in time",
  525: "the SSL handshake with the server failed",
  526: "the server's certificate is invalid",
  527: "the connection to the server failed",
};

/** What Cloudflare, which proxies the hosted API, means by its own 52x statuses. */
export const cloudflareReason = (status: number): string | undefined => CLOUDFLARE_REASONS[status];

/** The message for an error response without an API error body. */
export const statusMessage = (status: number, body: string): string => {
  const reason = cloudflareReason(status);
  if (reason) return `Cloudflare ${status}: ${reason}`;
  const trimmed = body.trim();
  return trimmed ? Array.from(trimmed).slice(0, 200).join("") : `HTTP ${status}`;
};

